window.SEORAP_DATA.copyTemplates.unshift({"id":"mail385-ownership","emoji":"✉️","title":"캐릭터 소유권","question":"캐릭터 소유권","replies":[{"label":"한국어","code":"ko","content":"안녕하세요. 현재 멀티 마을에서 기존 캐릭터의 소유권을 다른 계정으로 직접 넘기는 기능은 지원하지 않습니다.\n\n대신 ‘프로필 내보내기 → 공유 코드 만들기’로 코드를 전달하면, 상대방이 ‘공유 코드로 불러오기’에서 사진과 설정을 자신의 캐릭터로 복사할 수 있습니다. 받는 계정에는 빈 캐릭터 슬롯 1개가 필요합니다.\n\n이 방식은 별도의 캐릭터를 만드는 기능이므로 기존 멀티 캐릭터의 소유권이나 관계·생활 기록을 그대로 이전하지는 않습니다. 참고 부탁드립니다!"}]});
