window.SEORAP_DATA.copyTemplates.unshift({"id": "dv-multiplayer469-reply", "emoji": "🏘️", "title": "멀티 이사 뒤 첫 화면이 보일 때", "question": "캐릭터를 만들고 멀티에 참가한 뒤 다음 날 캐릭터가 안 보여요.", "replies": [{"label": "한국어", "code": "ko", "content": "멀티 마을로 이사한 캐릭터는 개인 마을 목록에서 빠집니다. 이때 앱을 다시 열면 첫 시작 화면에 머무를 수 있는 경로를 확인해, 로그인 상태에서 멀티 마을로 이어갈 수 있도록 수정했습니다. 현재 Android 1.0.417(469)은 내부 테스트 중입니다. 제보하신 캐릭터의 실제 삭제 여부는 아직 확인되지 않았으니 앱 삭제·데이터 초기화는 하지 말고, 같은 계정으로 로그인한 상태에서 참가했던 멀티 마을을 확인해 주세요."}]});

{const d=window.SEORAP_DATA,t=d.tasks.find(x=>x.id==='dv-multiplayer469');Object.assign(t,{"completed": true, "title": "469 · 멀티 생활 개선 / 내부 제공·Apple 재심사 접수", "summary": "1.0.417(469). Play 내부 release348 9/21 19:46 테스터 제공. Apple 최신 거절2.3.6 광고 표시 Yes 수정, 공개469 앱·광고제거상품19:54 재심사 대기 확인. 멀티 공유코드 적용·집 동기화·다른 화면 사용 가능한 이사·정원/대기 합산·새집너비·대표사진·빈화면·커피7종과 재료 소지품. 서버109-puw 및468 로그개선 배포,90파일 일치. Chrome/WebKit·정원·커피서버·503자산/서명 검증. 실제 제보자 데이터 복구 미확인. 새문구 한영일100%, dev EN/JA75.6%, 공개EN75.6%/JA75.5%. 앱소스dev 및별도공개브랜치,main은배포기록. Google프로덕션469 미승격."});const u=d.updates.find(x=>x.code===469);u.version="1.0.417 내부 제공 / Apple 심사 대기";u.items[3]="Play 내부 release348 제공·Apple469 앱과 광고 제거 상품 재심사 접수";}
window.SEORAP_DATA.documents.unshift({"id": "dv-multiplayer469-notes", "project": "서랍마을", "title": "469 수정·검증·배포 / Apple 재심사 기록", "content": "# 1.0.417 (469) — 멀티 생활 개선과 Apple 재심사\n\n- dev: 멀티 캐릭터 공유코드 적용, 집 변경 보존, 앱 내 백그라운드 이사와 정원 제한, 빈 캐릭터 화면 및 마을/이사 화면 정리, 새 집 크기, 커피 행동·재료 제작.\n- 개인 캐릭터가 모두 멀티로 이사한 뒤 첫 시작 화면만 보이는 경로에 멀티 이어하기를 추가. 제보자의 실제 데이터 유실 여부는 아직 확인하지 않았다.\n- Android 내부 테스트 및 이번 수정본 Apple 심사 제출 요청. Google 프로덕션 승격은 이번 버전에 대해 요청되지 않았다.\n\n## Apple 메타데이터 수정 — 2026-09-21\n\n- 최신 메시지 19:11: Guideline 2.3.6. 광고 포함 앱인데 연령 등급의 Advertising이 No로 설정되어 자동 심사 중단.\n- App Store Connect 광고를 Yes로 수정·저장한 뒤 재진입하여 체크 상태 확인.\n- 사용자 간 우편 기능에 맞춰 Messaging and Chat도 Yes로 수정.\n- 글로벌 13+, 한국 15+ 유지. 새 빌드469 연결 및 재심사 제출 완료.\n- 이전 Guideline 4 자동 프로필 입력 제거는 기존 467 소스에 포함되어 있다. 새 메시지는 광고 메타데이터에 관한 별도 사유다.\n\n## 구현 및 검증\n- Chrome/WebKit: 새 집 기본 12열 전체 폭, 빈 마을 제목 상단바 내부, 멀티 캐릭터 빈 화면 단순화.\n- Chrome/WebKit 실제 모듈: 선택한 멀티 캐릭터 공유코드 적용, 개인 캐릭터 수/집/제작 소지품 보존.\n- 커피머신: 캡슐·에스프레소·아메리카노·아이스·휘핑 우유·라떼·카푸치노·청소. 제작 완료 후 소지품, 휘핑 우유 소비, 서버 스냅샷 재계산 중복 지급 방지 검증.\n- 기존 및 승인 대기 합산 정원, 동시 요청, 관리자에게 복제된 승인 요청 중복 집계 방지, 이사/생성/운영진 정원 검증.\n- 집 편집 임시 목록이 최신 삭제·인테리어를 덮지 않도록 수정. 저장 완료 서버 응답 즉시 반영 및 오래된 응답 차단 검증.\n- 이사 요청의 그룹/마을/요청 ID를 고정하고 화면 이동과 분리. 계정 변경은 계속 차단.\n- 개인 캐릭터 0명일 때 로그인 사용자에게 멀티 이어하기 제공. 제보자의 데이터 복구 완료라고 단정하지 않음.\n- 360px 가구 편집/층 버튼 회귀, iOS 실제 인증 및 플랫폼 분리 통과.\n- 기존 check-shared-town-service는 과거 사전 80개 제한을 기대해 실패. 이번 작업에 맞춰 임의로 전체 테스트를 통과 처리하지 않음. 현재 100개 한도와 별도 정원·동기화 검증을 사용.\n- 전체 정적 번역 EN2260/2988, JA2259/2988: 모두75.6%. 새 문구·커피 내용은 한국어/영어/일본어 제공.\n\n## Play 출시노트\n<ko-KR>\n멀티 캐릭터에 공유 코드의 프로필과 사진을 적용할 수 있어요. 집 변경이 되돌아가거나 인테리어 반영이 늦는 문제를 개선했어요. 이사 중에도 다른 화면을 이용할 수 있고, 멀티 정원에 승인 대기 인원을 함께 반영해요. 새 집의 너비와 빈 캐릭터·이사 화면, 마을 대표 사진을 개선했어요. 커피머신에서 여러 커피와 휘핑 우유를 만들고, 소지한 휘핑 우유로 라떼·카푸치노를 만들 수 있어요.\n</ko-KR>\n<en-US>\nApply shared profiles and photos to selected multiplayer characters. Improved house edit synchronization, background moves within the app, and group limits including pending requests. Improved new house width, empty character screens, move selection and town thumbnails. Brew coffee and milk foam, then use stored milk foam to make lattes and cappuccinos.\n</en-US>\n<ja-JP>\n共有コードのプロフィールと写真を選択中のマルチキャラクターに適用できます。家の変更の同期、アプリ内でほかの画面を使いながらの引っ越し、承認待ちを含む定員管理を改善しました。新しい家の幅、キャラクターがいない画面、引っ越し選択、村の代表画像を改善しました。コーヒーやミルクフォームを作り、持ち物のフォームでラテやカプチーノを作れます。\n</ja-JP>\n\n## 배포 증거\n- Android 내부 release348: 2026-09-21 19:46 KST 내부 테스터에게 제공됨 확인. 1.0.417(469). Google 프로덕션 승격 없음.\n- Android 서명 AAB 503 웹자산 바이트 일치, jarsigner 검증 통과. 파일 C:/Users/Public/drawer-releases/drawervillage-1.0.417-469-internal.aab\n- SHA256: 04445423F48FA187EF699B77BF5DC804FF78F41E28AA18A86C22A8820B0767E6\n- dev 소스64fe70bf, 워크플로56b0fedb. Apple 공개 소스fe9f21f4(광장 및 미공개 경제 UI 제외), 모두 원격 반영.\n- Apple Actions35589873733 성공: Mac 실제 서명 및 App Store 업로드 accepted. 빌드ID1437b0bf-57a7-4bf3-b0f5-72c199df4e90. source 보고서56b0fedb는 실행 워크플로 SHA이고, checkout/검증 소스는fe9f21f4.\n- 운영 sharedTownApi: 실제00108-hun 배포 소스를 기준으로 필요한 변경만 병합. 이미 운영 중인 지갑/건물/권한 코드는 보존. 패치 docs/backend469.patch.\n- sharedTownApi00109-puw, 2026-09-21 19:49 KST 배포 완료. 서비스/런타임90파일 재다운로드 바이트 일치. 병합 산출물에서도 커피 제작/정원 테스트 통과. 이전468 생활 로그 개선도 서버 반영.\n- 첫 서버 배포 탐색10초 시간초과 후60초로 재시도 성공. Node20 종료 예정 경고는 후속 업그레이드 필요.\n- 제보자 실제 캐릭터 유실/복구는 미확인. 읽기 전용 집계 조회가 인덱스 사전조건 오류로 완료되지 않아 임의 복구나 데이터 수정을 하지 않음.\n- 번역: dev EN2260/2988(75.6%), JA2259/2988(75.6%). 공개 Apple 소스 EN2262/2993(75.6%), JA2261/2993(75.5%). 새 문구와 양 플랫폼 출시노트는 한영일 제공.\n- 구 웹 main은 공개 소스와 달라 전체 병합하지 않음. 새 기능은dev/별도공개소스에, 배포 기록은main에도 반영.\n\n## Apple 재심사 접수 — 2026-09-21 19:54 KST\n- 앱1.0.417(469) 및 광고 제거 IAP 모두 심사 대기 중 확인.\n- 제출ID a1d94db3-aa3b-444d-82aa-41f67e37d1a7. 광고 Yes, 메시지/채팅 Yes, 수출 정보 저장, 한영일 출시노트와 최신 심사 메모 저장.\n- 승인 후 자동 출시 / 모든 사용자 즉시 업데이트 설정 유지. 심사 통과나 일반 App Store 공개 완료를 의미하지 않음.\n"});

